    "source": "/** Lazy segment tree (range add + range sum), teaching version. 0-based, half-open [l, r). */\npublic class LazySegTree {\n    int n;\n    long[] total; // total[node] = sum of a[lo, hi) with tags at or above already applied\n    long[] lazy; // lazy[node] = amount still to add to EACH element under node\n\n    LazySegTree(long[] a) {\n        n = a.length;\n        total = new long[4 * Math.max(1, n)];\n        lazy = new long[4 * Math.max(1, n)];\n        if (n > 0) build(a, 1, 0, n);\n    }\n\n    void build(long[] a, int node, int lo, int hi) {\n        if (hi - lo == 1) { total[node] = a[lo]; return; }\n        int mid = lo + (hi - lo) / 2;\n        build(a, 2 * node, lo, mid);\n        build(a, 2 * node + 1, mid, hi);\n        total[node] = total[2 * node] + total[2 * node + 1];\n    }\n\n    /** Put tag v on node: every element in [lo, hi) gains v. */\n    void apply(int node, int lo, int hi, long v) {\n        total[node] += v * (hi - lo);\n        lazy[node] += v;\n    }\n\n    /** Hand the pending tag of node down to both children. */\n    void push(int node, int lo, int hi) {\n        if (lazy[node] == 0) return;\n        int mid = lo + (hi - lo) / 2;\n        apply(2 * node, lo, mid, lazy[node]);\n        apply(2 * node + 1, mid, hi, lazy[node]);\n        lazy[node] = 0;\n    }\n\n    /** a[i] += v for every i in [l, r). */\n    void add(int l, int r, long v) {\n        addRec(1, 0, n, l, r, v);\n    }\n\n    void addRec(int node, int lo, int hi, int l, int r, long v) {\n        if (r <= lo || hi <= l) return;\n        if (l <= lo && hi <= r) { apply(node, lo, hi, v); return; }\n        push(node, lo, hi);\n        int mid = lo + (hi - lo) / 2;\n        addRec(2 * node, lo, mid, l, r, v);\n        addRec(2 * node + 1, mid, hi, l, r, v);\n        total[node] = total[2 * node] + total[2 * node + 1];\n    }\n\n    /** Sum of a[l..r). */\n    long sum(int l, int r) {\n        return query(1, 0, n, l, r);\n    }\n\n    long query(int node, int lo, int hi, int l, int r) {\n        if (r <= lo || hi <= l) return 0;\n        if (l <= lo && hi <= r) return total[node];\n        push(node, lo, hi);\n        int mid = lo + (hi - lo) / 2;\n        return query(2 * node, lo, mid, l, r) + query(2 * node + 1, mid, hi, l, r);\n    }\n}\n",
